#!/usr/bin/env python3
"""Adds Garagio's Android settings to the project generated by `flutter create`.

Run from the repository root after `flutter create --platforms=android .`
(flutter create never overwrites files that already exist, so the committed
signing key and proguard rules survive). Fails loudly if the template has
changed so a patch no longer applies.
"""
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
APP = ROOT / "android" / "app"


def sub_once(text, old, new, what):
    if new.strip() and new.strip() in text:
        return text  # already patched
    if old not in text:
        sys.exit(f"patch_android: could not find {what!r} ({old!r})")
    return text.replace(old, new, 1)


# ---------------- AndroidManifest.xml ----------------
manifest_path = APP / "src" / "main" / "AndroidManifest.xml"
m = manifest_path.read_text()

permissions = """
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>
    <uses-permission android:name="android.permission.VIBRATE"/>
    <uses-permission android:name="android.permission.READ_CONTACTS"/>
"""
if "POST_NOTIFICATIONS" not in m:
    m = re.sub(r"(<manifest[^>]*>)", r"\1" + permissions, m, count=1)

m = re.sub(r'android:label="[^"]*"', 'android:label="Garagio"', m, count=1)

receivers = """
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
    </application>"""
if "ScheduledNotificationReceiver" not in m:
    m = m.replace("</application>", receivers, 1)

queries = """
        <intent>
            <action android:name="android.intent.action.DIAL" />
            <data android:scheme="tel" />
        </intent>
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
    </queries>"""
if 'android:scheme="tel"' not in m:
    if "</queries>" in m:
        m = m.replace("</queries>", queries, 1)
    else:
        m = m.replace("</manifest>", "    <queries>" + queries + "\n</manifest>", 1)

manifest_path.write_text(m)

# ---------------- app build file ----------------
kts = APP / "build.gradle.kts"
groovy = APP / "build.gradle"
if kts.exists():
    g = kts.read_text()
    g = sub_once(g, "compileOptions {", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", "compileOptions")
    g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = maxOf(flutter.minSdkVersion, 23)", g, count=1)
    signing = """signingConfigs {
        create("release") {
            storeFile = file("garagio-test.jks")
            storePassword = "garagio-test"
            keyAlias = "garagio"
            keyPassword = "garagio-test"
        }
    }

    buildTypes {"""
    g = sub_once(g, "buildTypes {", signing, "buildTypes")
    g = g.replace('signingConfigs.getByName("debug")', 'signingConfigs.getByName("release")')
    if "desugar_jdk_libs" not in g:
        g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
    kts.write_text(g)
elif groovy.exists():
    g = groovy.read_text()
    g = sub_once(g, "compileOptions {", "compileOptions {\n        coreLibraryDesugaringEnabled true", "compileOptions")
    g = re.sub(r"minSdk(Version)?\s*=?\s*flutter\.minSdkVersion", "minSdkVersion Math.max(flutter.minSdkVersion, 23)", g, count=1)
    signing = """signingConfigs {
        release {
            storeFile file("garagio-test.jks")
            storePassword "garagio-test"
            keyAlias "garagio"
            keyPassword "garagio-test"
        }
    }

    buildTypes {"""
    g = sub_once(g, "buildTypes {", signing, "buildTypes")
    g = g.replace("signingConfigs.debug", "signingConfigs.release")
    if "desugar_jdk_libs" not in g:
        g += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
    groovy.write_text(g)
else:
    sys.exit("patch_android: no android/app/build.gradle(.kts) found")

print("patch_android: Android project patched")
